/* ===== Хімія: вживання, ефекти, залежність ===== */
function chem(){ if(!st.chem) st.chem=blankChem(); const c=st.chem; if(!c.sceneNo) c.sceneNo=1; ['scene','day','used','addictions'].forEach(k=>{ if(!Array.isArray(c[k])) c[k]=[]; }); if(!c.uses) c.uses={}; if(!c.session) c.session=1; if(!c.dayNo) c.dayNo=1; if(c.restDay==null) c.restDay=0; return c; }
