  const nA=c.addictions.length; const tint = nA>=3 ? 'hsla(2,75%,48%,.34)' : nA===2 ? 'hsla(24,85%,50%,.30)' : nA===1 ? 'hsla(48,90%,52%,.30)' : 'transparent';
