function openRoller(open){
  const p=document.getElementById('roller'); const b=document.getElementById('roller-btn');
  p.hidden=!open; document.body.classList.toggle('roller-open', open); if(b) b.setAttribute('aria-expanded', String(open));
  if(open){ renderRoller(); const h=p.querySelector('h2'); if(h) h.focus(); }
  else if(b) b.focus();
}
function rollerClick(b){ if(!b) return;
  if(b.tagName==='SELECT' || (b.tagName==='INPUT')) return;
  const k=b.dataset.r;
  switch(k){
    case 'attr': R.attr=b.dataset.v; break;
    case 'luckattr': R.attr='UDCH'; break;
    case 'boost': R.boost=Math.max(0,Math.min(2,R.boost+(+b.dataset.d))); break;
    case 'pen': R.pen=Math.max(0,Math.min(2,R.pen+(+b.dataset.d))); break;
    case 'mod': R.mod=Math.max(-3,Math.min(3,R.mod+(+b.dataset.d))); break;
    case 'preset': { const p=ROLL_PRESETS[+b.dataset.v]; R.last=null; R.am={}; R.psi=''; R.hint=''; R.dmgKey=null; R.dmgUser=false; R.type=p.t; if(p.a){ R.attr=p.a; R.skill=p.s; } else applyTypeDefaults(p.t); break; }
    case 'xpreset': R.last=null; applyPreset(extraPresets()[+b.dataset.v]); R.dmgUser=false; break;
    case 'dmg': doDamage(); break;
    case 'dmgre': { const L=R.last; if(L&&L.dmg){ L.dmg.rerolled=true; const p=L.dmg.p; L.dmg.r1=rollDice(p); if(L.dmg.r2) L.dmg.r2=rollDice(p); ['silent','crit','robot'].forEach(k=>{ if(L.dmg.extra[k]!=null) L.dmg.extra[k]=rnd(6); }); logDamage(L,compute(st)); } break; }
    case 'pool': { const k=+b.dataset.k; R.pool[k]=Math.max(0,Math.min(10,R.pool[k]+(+b.dataset.d))); break; }
    case 'poolroll': rollPool(); break;
    case 'roll': doRoll(); break;
    case 'aspect': invokeAspect(); render(); return;
    case 'modasp': { const x=rollMods()[+b.dataset.v]; if(x && !x.m.u){ const n=x.m.n.trim(); invokeAspect({label:'модифікації «'+n+'»', use:()=>{ x.m.u=true; }, msg:'Модифікація «'+n+'»: безкоштовне Посилення на цю сесію використано.'}); } render(); return; }
    case 'sitasp': { const a=(st.sit||[])[+b.dataset.v]; if(a && a.inv>0){ invokeAspect({label:'аспекту «'+a.t+'»', use:()=>{ a.inv=Math.max(0,a.inv-1); }, msg:'Аспект «'+a.t+'»: безкоштовне Посилення використано, лишилося '+Math.max(0,a.inv-1)+'.'}); } render(); return; }
    case 'xp': giveXp(+b.dataset.v, b.dataset.k); return;
    case 'fmode': R.fateMode=b.dataset.v; break;
    case 'fate': rollFate(); break;
    default: return;
  }
  renderRoller();
}
function rollerChange(t){ if(!t || !t.dataset || !t.dataset.r) return;
  const k=t.dataset.r;
  if(k==='type'){ if(R.type!==t.value){ R.last=null; R.am={}; } R.type=t.value; applyTypeDefaults(R.type); }
  else if(k==='skill'){ R.skill=t.value; if(R.am) Object.keys(R.am).filter(x=>x.startsWith('spec')).forEach(x=>delete R.am[x]); }
  else if(k==='spend') R.spend=t.checked;
  else if(k==='addon') R.addOn=t.checked;
  else if(k==='poison') R.poison=t.value;
  else if(k==='am'){ R.am=R.am||{}; R.am[t.dataset.k]=t.checked; }
  else if(k==='party') R.party=+t.value;
  else if(k==='dmgw'){ R.dmgKey=t.value; R.dmgUser=true; if(R.last) R.last.dmg=null; }
  else if(k==='dopt'){ R.dmgOpt[t.dataset.k]=t.checked; if(R.last && R.last.dmg){ if(t.dataset.k==='auto'||t.dataset.k==='dual') R.last.dmg=null; else logDamage(R.last, compute(st)); } }
  renderRoller();
}





/* ===== Псионіка в перевірках ===== */
const PSI_PRESETS = {
  'Пси-удар':{l:'Пси-удар (ІН, атака)', a:'IN', s:'', t:'attack', h:'Пси-удар: атака ІН як зброєю для бою на відстані. Шкода — у блоці «Шкода» після кидка.'},
  'Телекінез':{l:'Телекінез (ІН)', a:'IN', s:'', t:'overcome', h:'Телекінез: перевірка ІН потрібна, щоб пересунути предмет вагою до кількох кілограмів або рухати дрібні речі з особливою точністю. Доглядач може дати Послаблення чи заборонити спробу.'},
  'Сканування розуму':{l:'Читання думок (ІН + Маніпуляція)', a:'IN', s:'Маніпуляція', t:'learn', h:'Сканування розуму: поверхневі емоції зчитуються без перевірки, а для читання думок потрібна ІН + Маніпуляція. Можна застосовувати потай.'},
  'Навіювання':{l:'Навіювання (ІН + Примус)', a:'IN', s:'Примус', t:'overcome', h:'Навіювання: раз за сцену. Наприкінці сцени ефект припиняється, і ціль зрозуміє, що з нею сталося щось дивне.'},
  'Послання':{l:'Далеке послання (ІН + Маніпуляція)', a:'IN', s:'Маніпуляція', t:'overcome', h:'Послання: −1 за кожну невідому річ — ім\'я, зовнішність, приблизне місце. Зменш модифікатор. У разі невдачі здатність недоступна до наступного дня.'},
  'Біосканер':{l:'Біосканер (СПР)', a:'SPR', s:'', t:'learn', h:'Біосканер: перевірка СПР, щоб визначити точне розташування й біологічний вид живих істот поруч.'}
};
function extraPresets(){
  const out=[]; const names=st.perks.map(p=>p.n);
  if(gunsOn()){ const pk=['Зброяр','Броняр'].filter(n=>names.includes(n));
    out.push({l:'Модифікація (ІН + Техніка'+(pk.length?', +1':'')+')', a:'IN', s:'Техніка', t:'gmod', mod:pk.length?1:0, gun:true,
      h: pk.length ? pk.join(' / ')+': +1 до перевірок ІН + Техніка, коли вдосконалюєш '+(pk.length===2?'зброю чи броню':pk[0]==='Зброяр'?'зброю':'броню')+' — уже в модифікаторі.'+(pk.length===1?' Для '+(pk[0]==='Зброяр'?'броні потрібен «Броняр»':'зброї потрібен «Зброяр»')+'.':'')+' Встановлення коштує 10 кришок.'
        : 'Для створення та встановлення модифікацій персонажу потрібен перк «Зброяр» (зброя) чи «Броняр» (броня). Без нього модифікацію не встановиш.'}); }
  Object.keys(PSI_PRESETS).forEach(n=>{ if(names.includes(n)) out.push(Object.assign({psi:n},PSI_PRESETS[n])); });
  const lie=['Сканування розуму','Емпатія'].filter(n=>names.includes(n));
  if(lie.length) out.push({l:'Розпізнати брехню (СПР + Маніпуляція, +2)', a:'SPR', s:'Маніпуляція', t:'learn', mod:2, h:lie.join(' / ')+': +2 до перевірок СПР + Маніпуляція, щоб розпізнати брехню чи замовчування. Модифікатор уже виставлено.'});
  return out;
}
function favTrickBonus(psiName){
  return st.perks.some(p=>p.n==='Улюблений фокус' && (p.note||'').toLowerCase().includes(psiName.toLowerCase().split(' ')[0])) ? 1 : 0;
}
function applyPreset(p){
  R.type=p.t; R.psi=p.psi||''; R.hint=p.h||'';
  if(p.a){ R.attr=p.a; R.skill=p.s; } else applyTypeDefaults(p.t);
  let mod = p.mod||0;
  if(p.psi){ const fb=favTrickBonus(p.psi); if(fb){ mod+=fb; R.hint+=' Улюблений фокус: +1 — уже в модифікаторі.'; } }
  if(p.mod!=null || p.psi) R.mod=mod;
  R.dmgKey=null;
}

/* ===== Шкода зброї ===== */
const DICE_UP = {'1d6':'1d10','1d10':'2d6','2d6':'3d6','3d6':'3d6'};
function parseDmg(str){
  const s=String(str||'').toLowerCase().replace(/\s+/g,'');
  if(/менш/.test(s)) return {low:true, terms:[{n:2,s:6}], flat:0};
  const terms=[]; let flat=0;
  const m=s.match(/(\d*)d(\d+)/); if(!m) return null;
  terms.push({n:+m[1]||1, s:+m[2]});
  let rest=s.slice(s.indexOf(m[0])+m[0].length), x;
  while((x=rest.match(/^([+-])(\d*)d(\d+)|^([+-]\d+)(?![\dd])/))){ if(x[3]){ if(x[1]==='+') terms.push({n:+x[2]||1, s:+x[3]}); } else flat+=+x[4]; rest=rest.slice(x[0].length); }
  return {low:false, terms, flat};
}
function unarmedDmg(d){
  const n=d.allPerks.filter(p=>p==='Залізні кулаки').length;
  if(n>=2) return '2d6'; if(n===1||d.powerArmor) return '1d10'; return 'менший з 2d6';
}
/* Вид атаки за навичкою: лише для конкретних перевірок (Стрільба, Герць, Техніка) */
function dmgFilterMode(skill){ return skill==='Стрільба'?'ranged':skill==='Герць'?'melee':skill==='Техніка'?'explosive':''; }
const WK_PRE="(?:^|[^а-яіїєґa-z'])";
const WK_MELEE=new RegExp(WK_PRE+"(ближн|кастет|ніж|нож|меч|спис|битк|бит[аиу]|лом|кувалд|молот|сокир|різак|пилоніж|бензопил|кулак|рукавиц|погонич|батіг|батог|шишкебаб|вакідзаші|катан|тесак|мачете|палиц|кийок|кийк|пазур|кігт|клинок|шабл|кинджал)");
const WK_RANGED=new RegExp(WK_PRE+"(стрілец|пістолет|гвинтівк|рушниц|дробовик|кулемет|автомат|лук|арбалет|револьвер|обріз|двостволк|гармат|мініган|гатлінг|базук|гранатомет|вогнемет|бластер|голкостріл|снайпер|самопал|плазмомет|турбоплазмомет|томмі|маузер|desert|pancor|маслянк|h&k|ak112|fal|підпалювач|ствол|бій на відстані)");
function weaponKind(c){
  if(c.key==='unarmed') return 'melee'; if(c.expl) return 'explosive';
  const w=c.w; if(!w) return 'any'; if(w.claw) return 'melee'; if(w.auto==='psi') return 'psi';
  if(w.r==='melee' || w.rof==='melee') return 'melee';
  if(w.zone || ['1','2','max'].includes(w.r) || ['single','semi','auto'].includes(w.rof)) return 'ranged';
  for(const t of [catNorm(w.n), catNorm(w.note)]){ const m=WK_MELEE.test(t), r=WK_RANGED.test(t); if(m&&!r) return 'melee'; if(r&&!m) return 'ranged'; }
  return 'any';
}
/* Зброя для кидка шкоди з урахуванням виду атаки; якщо відповідної немає — уся */
function dmgChoicesFor(d, skill){
  const all=dmgChoices(d); const m=dmgFilterMode(skill); if(!m) return {list:all, m:'', fb:false};
  const ok=all.filter(c=>{ const k=weaponKind(c); return m==='explosive' ? k==='explosive' : (k===m || k==='any'); });
  return ok.length ? {list:ok, m, fb:false} : {list:all, m, fb:true};
}
function dmgChoices(d){
  const out=st.weapons.map((w,i)=>({key:'w'+i, name:weaponName(w)||'Зброя', d:weaponDmg(w), w}));
  st.other.forEach((o,i)=>{ const m=String(o.note||'').match(/(\d+d\d+(?:\s*[+-]\s*\d+(?:d\d+)?)*)/); if(m && /гранат|динаміт|c-4|с-4|вибух|ракет|постріл|молотов|заряд/i.test(o.n||'')) out.push({key:'o'+i, name:o.n+(String(o.q||'').trim()!==''?' ×'+String(o.q).trim():''), d:m[1].replace(/\s+/g,''), o, expl:true}); });
  if(st.species!=='claw') out.push({key:'unarmed', name:'Беззбройні атаки', d:d?unarmedDmg(d):''});
  return out;
}
function defaultDmgKey(ch, mode){
  if(R.psi==='Пси-удар'){ const i=st.weapons.findIndex(w=>w.auto==='psi'); if(i>=0) return 'w'+i; }
  if(mode==='explosive'){ const g=ch.find(c=>c.expl); if(g) return g.key; }
  const keys=ch.map(c=>c.key);
  const mw=mainWeapon(st)||st.weapons[bestWeaponIndex(st.weapons)]; const i=mw?st.weapons.indexOf(mw):-1;
  if(i>=0 && keys.includes('w'+i)) return 'w'+i;
  const ws=ch.filter(c=>c.w); if(ws.length){ const bi=bestWeaponIndex(ws.map(c=>c.w)); if(bi>=0) return ws[bi].key; }
  return ch[0]?ch[0].key:'unarmed';
}
function weaponTraits(c, mode, d){
  const t=[]; let ignore=0;
  const w=c.w; const has=p=>d.allPerks.includes(p);
  if(w){
    const e=ENERGY[w.en||'']; let ei=0; if(w.en==='laser') ei=1; if(w.en==='plasma') ei=2; if(w.en==='gauss') ei=3;
    const ni=noteIgnore(w.note); ignore += w.fixEn ? Math.max(ei, ni) : ei+ni;
    if(w.en==='cryo' && !(gunsOn() && w.fixEn)) t.push('Кріо: на критичному успіху замість шкоди можна заморозити ціль.');
    if(w.claw) ignore+=1;
    if(w.auto==='psi' && !/вогон|електр|холод/.test(w.n)) t.push('Психічна шкода: ігнорує фізичну броню, діє лише на живих істот.');
    if((w.en && w.en!=='') || (w.auto==='psi' && /вогон|електр|холод/.test(w.n))) { if(has('Розпад')) t.push('Розпад: якщо вб\'єш ціль, усі істоти в її зоні отримують 1d6 фізичної шкоди, що ігнорує броню (і ти, і союзники).'); }
  }
  if(c.o) ignore+=noteIgnore(c.o.note);
  if(mode==='melee' && has('Бронебійний удар')) ignore+=1;
  if(ignore>=99) t.unshift('Повністю ігнорує фізичну броню супротивника.'); else if(ignore) t.unshift('Ігнорує '+ignore+' фізичної броні супротивника.');
  if(w && gunsOn() && !w.claw && w.auto!=='psi'){
    if(w.zone) t.push('Шкода всім у зоні влучання.');
    if(w.r && GUN_RANGE_T[w.r] && !(w.r==='melee' && (w.rof==='melee'||!w.rof))) t.push('Дальність '+GUN_RANGE[w.r]+' — '+GUN_RANGE_T[w.r].charAt(0).toLowerCase()+GUN_RANGE_T[w.r].slice(1));
    const rf = w.rof || (w.r==='melee' ? 'melee' : ''); if(rf && GUN_ROF_T[rf]) t.push((rf==='melee'?'Ближній бій':GUN_ROF_N[rf].charAt(0).toUpperCase()+GUN_ROF_N[rf].slice(1))+' — '+GUN_ROF_T[rf].charAt(0).toLowerCase()+GUN_ROF_T[rf].slice(1));
    if(modList(w).length) t.push('Модифікації: '+modList(w).map(m=>m.n.trim()+(m.u?' (Посилення використано)':'')).join(', ')+'.');
  }
  if(c.expl) t.unshift('Шкода всім створінням у зоні ураження, включно зі спільниками й тобою.');
  return t;
}
/* Додаткові властивості зброї з таблиць доповнення (або з примітки) — підказка під час кидка шкоди.
   Те, що вже показано окремо (ігнорування броні, шкода по зоні, тип енергії, крамничні дані), не повторюється. */
function weaponPropsHint(c){
  if(!gunsOn()) return '';
  const it=c.w||c.o; if(!it || (c.w && (c.w.claw || c.w.auto==='psi'))) return '';
  const key=catNorm(c.w ? c.w.n : c.o.n).trim();
  let src='', fromBook=false;
  if(c.w){ const r=GUN_ROWS.find(x=>catNorm(x[1])===key); if(r){ src=r[7]; fromBook=true; } }
  else { const r=GUN_BOOM.find(x=>catNorm(x[0])===key); if(r){ src=r[3]; fromBook=true; } }
  if(!fromBook) src=String(it.note||'').split(/;\s*/).filter(x=>x && !/^\d+\s*к$|^безкоштовн|^уся зона$|^дальність \d|^\d+d\d+/i.test(x.trim())).join('; ');
  src=src.replace(/^Завдає шкоди всім у зоні влучання[;.]\s*/i,'').replace(/^./,ch=>ch.toUpperCase());
  const keep=src.split(/(?<=\.)\s+/).map(x=>x.trim()).filter(x=>x &&
    !/^(Лазерн|Плазмов|Гаус|Електричн|Енергетичн|Кріо)[а-яіїєґ]*\.$/i.test(x) &&
    !/ігнору/i.test(x) && !/рідкісна річ|Придбати не можна|Завдає роботам та електроніці/i.test(x));
  if(!keep.length) return '';
  return '<p class="rnote rprops"><b>Властивості '+(c.o?'вибухівки':'зброї')+':</b> '+esc(keep.join(' '))+'</p>';
}
/* Роботи (крім кіборгів) не вживають хімії */
function robotBody(){ return st.species==='robot' && !st.feats.includes('Кіборг'); }
function isElectric(c){ return !!(c.w && (c.w.en==='electric' || (c.w.auto==='psi' && /електр/.test(c.w.n)))); }
function dmgBonuses(mode, d, opt, c){
  const has=p=>d.allPerks.includes(p); const b=[];
  const psi=!!(c && c.w && c.w.auto==='psi');
  if(mode==='ranged' && !psi && has('Бонусна шкода в бою на відстані')) b.push(['Бонусна шкода в бою на відстані',2]);
  if(mode==='melee' && has('Бонусна шкода в ближньому бою')) b.push(['Бонусна шкода в ближньому бою',2]);
  if(mode==='explosive' && has('Бонусна шкода вибухівкою')) b.push(['Бонусна шкода вибухівкою',2]);
  if(!psi && d.has('Камікадзе')) b.push(['Камікадзе',2]);
  if(!psi && !robotBody() && (opt.psycho || (typeof chemHas==='function' && chemHas('Психо')))) b.push(['Психо',2]);
  if(opt.norm2) b.push(['Звичайний ефект',2]);
  return b;
}
function rollDice(p){ return p.low ? (()=>{ const a=rnd(6), c=rnd(6); return {vals:[a,c], sum:Math.min(a,c), low:true}; })() : (()=>{ const vals=[]; p.terms.forEach(t=>{ for(let i=0;i<t.n;i++) vals.push(rnd(t.s)); }); return {vals, sum:vals.reduce((x,y)=>x+y,0)}; })(); }
function maxDice(p){ return p.low ? 6 : p.terms.reduce((s,t)=>s+t.n*t.s,0); }
function doDamage(){
  const L=R.last; if(!L) return; const d=compute(st);
  const mode=attackMode(L.skillName, L.attr); const ch=dmgChoicesFor(d, L.skillName).list;
  const c=ch.find(x=>x.key===R.dmgKey) || ch.find(x=>x.key===defaultDmgKey(ch,mode)); if(!c) return;
  const psiW=!!(c.w && c.w.auto==='psi');
  let dstr=c.d; if(R.dmgOpt.dual && !psiW && DICE_UP[dstr]) dstr=DICE_UP[dstr];
  const p=parseDmg(dstr); if(!p){ toast('Не вдалося розібрати шкоду зброї «'+c.d+'». Виправ поле «Шкода» у Мотлосі.','bad'); return; }
  let spent='';
  if(c.o){ const qs=String(c.o.q==null?'':c.o.q).trim(); const q=qs===''?1:parseInt(qs,10);
    if(!isNaN(q)){ if(q<=0){ toast('«'+c.o.n+'» не лишилося — кинути нічого.','bad'); return; } c.o.q=String(q-1); spent='Витрачено: '+c.o.n+', лишилося '+(q-1)+'.'; persist(); } }
  const r1=rollDice(p); const r2 = R.dmgOpt.auto && !psiW ? rollDice(p) : null;
  L.dmg={key:c.key, name:c.name, dstr, p, r1, r2, extra:{}, rerolled:L.dmg?L.dmg.rerolled:false, time:Date.now(), spent};
  L.dmgDone=true; if(spent) toast(spent);
  logDamage(L, d);
}
function dmgExtra(L, k){ if(L.dmg.extra[k]==null) L.dmg.extra[k]=rnd(6); return L.dmg.extra[k]; }
function ch0(L,d){ return dmgChoices(d).find(x=>x.key===L.dmg.key); }
function dmgTotal(L, d){
  const D=L.dmg; const mode=attackMode(L.skillName, L.attr); const opt=R.dmgOpt; const parts=[];
  let base;
  const psiW=!!(ch0(L,d) && ch0(L,d).w && ch0(L,d).w.auto==='psi');
  if(opt.silent && !psiW){ base=maxDice(D.p); parts.push(['Максимум кісток (Тиха смерть)', base]); parts.push(['Тиха смерть +1d6', dmgExtra(L,'silent')]); }
  else { const best = D.r2 && !psiW && D.r2.sum>D.r1.sum ? D.r2 : D.r1; base=best.sum; parts.push([(D.p.low?'менший з 2d6':D.p.terms.map(t=>t.n+'d'+t.s).join('+'))+(D.r2?' (краща з двох)':''), base]); }
  if(D.p.flat) parts.push(['Бонус зброї', D.p.flat]);
  const ch=dmgChoices(d).find(x=>x.key===D.key);
  dmgBonuses(mode, d, opt, ch).forEach(b=>parts.push(b));
  if(opt.crit) parts.push(['Критичний ефект +1d6', dmgExtra(L,'crit')]);
  if(opt.robot && ch && isElectric(ch)) parts.push(['Електрична: робот чи електроніка +1d6', dmgExtra(L,'robot')]);
  const total=Math.max(0, parts.reduce((s,x)=>s+x[1],0));
  return {parts, total};
}
function poisonRes(L){ if(!L.poison||!L.poisonRoll) return ''; const P=L.poisonRoll; return '<div class="rpoisres"><span class="dsep">отрута</span>'+P.vals.map(v=>dieChip(v, parseDmg(L.poison.dice).terms[0].s, 'kept aspect','')).join('')+'<b>+'+P.sum+'</b> <span>шкоди отрутою ('+esc(L.poison.n.toLowerCase())+') — ігнорує броню, крім силової та хімзахисту. Діє, лише якщо після броні атака завдала хоча б 1 фізичної шкоди.</span></div>'; }
function logDamage(L, d){
  const t=dmgTotal(L, d);
  const h={kind:'dmg', total:t.total, label:'Шкода: '+L.dmg.name+' ('+L.dmg.dstr+')'+(L.poison&&L.poisonRoll?' + отрута '+L.poisonRoll.sum:''), time:L.dmg.time};
  const i=R.hist.findIndex(x=>x.kind==='dmg' && x.time===L.dmg.time);
  if(i>=0) R.hist[i]=h; else pushHist(h);
}
function renderDamage(L, d){
  const mode=attackMode(L.skillName, L.attr);
  if(!(L.verdict>=1 || mode==='explosive')) return '';
  const has=p=>d.allPerks.includes(p); const F=dmgChoicesFor(d, L.skillName); const ch=F.list;
  if(!R.dmgKey || !ch.some(c=>c.key===R.dmgKey)) R.dmgKey=defaultDmgKey(ch, mode);
  const c=ch.find(x=>x.key===R.dmgKey);
  const opt=R.dmgOpt;
  const tog=(k,l,dis)=>'<label class="tog"><input type="checkbox" id="dm-'+k+'" data-r="dopt" data-k="'+k+'"'+(opt[k]?' checked':'')+(dis?' disabled':'')+'> '+l+'</label>';
  const toggles=[];
  if(L.verdict>=2 || (L.verdict===1 && ((mode==='ranged'&&has('Прицільний постріл'))||(mode==='melee'&&has('Точний удар'))))) toggles.push(tog('norm2','Звичайний ефект: +2 шкоди'));
  if(L.verdict===3) toggles.push(tog('crit','Критичний ефект: +1d6 шкоди'));
  const psiW = !!(c && c.w && c.w.auto==='psi');
  if(!psiW && !robotBody()) toggles.push(typeof chemHas==='function' && chemHas('Психо') ? '<label class="tog"><input type="checkbox" checked disabled> Психо діє (+2 шкоди) — вжито з мотлоху</label>' : tog('psycho','Психо діє (+2 шкоди)'));
  if(c && isElectric(c)) toggles.push(tog('robot','Ціль — робот чи електроніка (+1d6)'));
  if(!psiW && has('Тиха смерть')) toggles.push(tog('silent','Тиха смерть: ціль не очікує атаки (максимум + 1d6)'));
  if(!psiW && has('Автоматний псих') && mode==='ranged' && !(gunsOn() && c && c.w && c.w.rof && c.w.rof!=='auto')) toggles.push(tog('auto','Автоматний псих: витратити 1 Припас, кинути двічі'));
  if(!psiW && has('З двох рук') && mode==='ranged') toggles.push(tog('dual','З двох рук: дві однакові зброї (категорія вища)'));
  const traits = c ? weaponTraits(c, mode, d) : [];
  const props = c ? weaponPropsHint(c) : '';
  const fav = c && c.w && c.w.fav ? '<p class="rnote"><b>Улюблена зброя:</b> +1 до перевірки атаки вже враховано автоматично.</p>' : '';
  let out='<div class="rdmg"><h4>Шкода</h4>'+(F.fb?'<p class="rhint">'+esc(F.m==='explosive'?'У мотлосі немає гранат чи вибухівки з кубиками шкоди в примітці — показано всю зброю.':F.m==='melee'?'У мотлосі немає зброї ближнього бою — показано всю зброю.':'У мотлосі немає зброї для бою на відстані — показано всю зброю.')+'</p>':'')+'<div class="rdmgsel"><select id="r-dmgw" data-r="dmgw" aria-label="Зброя для кидка шкоди">'+ch.map(x=>'<option value="'+x.key+'"'+(x.key===R.dmgKey?' selected':'')+'>'+esc(x.name)+' · '+esc(x.d)+'</option>').join('')+'</select></div>'+
    (traits.length?'<ul class="rtraits">'+traits.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+props+fav+
    '<div class="rdopts">'+toggles.join('')+'</div>';
  if(L.dmg && L.dmg.key===R.dmgKey){
    const t=dmgTotal(L,d); const D=L.dmg;
    const chips = (opt.silent ? '' : D.r1.vals.map(v=>dieChip(v, D.p.low?6:D.p.terms[0].s, (D.r2 && D.r2.sum>D.r1.sum)?'drop':(D.p.low && v!==D.r1.sum && D.r1.vals[0]!==D.r1.vals[1]?'drop':'kept'),'')).join('') + (D.r2 ? '<span class="dsep">другий кидок</span>'+D.r2.vals.map(v=>dieChip(v, D.p.terms[0].s, D.r2.sum>D.r1.sum?'kept':'drop','')).join('') : ''))
      + ['silent','crit','robot'].filter(k=>D.extra[k]!=null && (k!=='robot'||opt.robot) && opt[k]).map(k=>'<span class="dsep">+1d6</span>'+dieChip(D.extra[k],6,'kept skill','')).join('');
    out+='<div class="rdres"><div class="rdice">'+chips+'</div><div class="rsum"><span class="rform">'+esc(t.parts.map(p=>p[1]).join(' + '))+' =</span><b class="rtot">'+t.total+'</b><span class="rform">шкоди</span></div>'+
      '<ul class="rsteps">'+t.parts.map(p=>'<li>'+esc(p[0])+': '+p[1]+'</li>').join('')+'</ul>'+(D.spent?'<p class="rnote">'+esc(D.spent)+'</p>':'')+poisonRes(L)+
      (has('Бойові рефлекси') && !D.rerolled ? '<button type="button" class="btn sm" data-r="dmgre">Бойові рефлекси: перекинути</button>' : '')+'</div>';
  } else {
    out+='<button type="button" class="btn rust" data-r="dmg">'+icon('dice')+'Кинути шкоду'+(c?' ('+esc(c.d)+')':'')+'</button>';
  }
  return out+'</div>';
}

function chemRollNote(d){
  if(typeof chemEffects!=='function') return '';
  const effs=chemEffects().filter(e=>e.attr||e.dmg); const un=unsatAddictions(); const ap=addictionPenalty(un.length);
  let h='';
  if(effs.length) h+='<p class="rhint">Діє хімія: '+esc(effs.map(e=>e.drug+' — '+e.t).join('; '))+'. Атрибути вище вже враховують її.</p>';
  if(un.length) h+='<label class="tog raddp"><input type="checkbox" id="r-addon" data-r="addon"'+(R.addOn!==false?' checked':'')+'> Залежність без дози ('+esc(un.map(a=>a.drug).join(', '))+'): <b>'+esc(ap.t)+'</b></label>';
  return h;
}

